def without_hidden_record(region):
    """Remove the four arguments of nonprinting historical statement metadata."""
    while True:
        m = re.search(r'\\StatementRecord\{', region)
        if m is None:
            return region
        j = m.end() - 1
        for _ in range(4):
            while region[j].isspace():
                j += 1
            if region[j] != '{':
                raise ValueError('Malformed StatementRecord argument')
            level = 1
            j += 1
