def without_hidden_record(region):
    """Remove historical statement and uses/used-by metadata arguments."""
    arities = {'StatementRecord': 4, 'Uses': 1, 'UsedBy': 1}
    while True:
        m = re.search(r'\\(StatementRecord|Uses|UsedBy)\s*\{', region)
        if m is None:
            return region
        j = m.end() - 1
        for _ in range(arities[m.group(1)]):
            while region[j].isspace():
                j += 1
            if region[j] != '{':
                raise ValueError('Malformed metadata argument: ' + m.group(1))
            level = 1
            j += 1
            while level:
                if region[j] == '{' and region[j-1] != '\\':
                    level += 1
                elif region[j] == '}' and region[j-1] != '\\':
                    level -= 1
                j += 1
        region = region[:m.start()] + region[j:]

